// True if (x, y) - 0<=x<800, 0<=y<400 - is land.
inline bool landAt(int x, int y) {
    uint8_t byte = pgm_read_byte(&LAND_MASK[y * LAND_MASK_ROW_BYTES + x / 8]);
    return (byte >> (7 - (x % 8))) & 1;
}
